//! Saved-observation hreflang and pagination report tables.
use crate::{Page,Result,path_reports::Report};
use std::collections::{BTreeMap,BTreeSet};
pub const KINDS:[&str;9]=["all-hreflang","non-200-hreflang","unlinked-hreflang","missing-hreflang-returns","inconsistent-hreflang-returns","noncanonical-hreflang","noindex-hreflang","non-200-pagination","unlinked-pagination"];
pub fn hreflang(pages:&[Page],kind:&str)->Result<Report>{
 if !KINDS[..7].contains(&kind){return Err("Unknown hreflang report".into())}
 let by:BTreeMap<_,_>=pages.iter().map(|page|(page.url.as_str(),page)).collect();let linked:BTreeSet<_>=pages.iter().filter(|page|page.internal).flat_map(|page|page.links.iter()).filter(|link|link.kind=="anchor"||link.kind=="area").map(|link|link.url.as_str()).collect();
 let mut report=Report{kind:kind.into(),headers:["Source","Language","Target","Target Status","Observed Hyperlink Inlink","Return Link","Source Self Languages","Finding"].into_iter().map(String::from).collect(),rows:Vec::new(),truncated:false,scope:"Recorded hreflang declarations only. Unknown target status is blank; missing returns require a known HTTP 200 HTML target with confirmed extraction. Inconsistent language compares recorded return labels against the source's self-reference labels. Unlinked means no observed anchor/area from saved internal pages, not site-wide absence. Legacy extraction, language registry validity and equivalent content remain uncertified. No network requests; 50000-row limit is explicit.".into()};
 for source in pages{let self_languages:BTreeSet<_>=source.hreflang.iter().filter(|(_,url)|url==&source.url).map(|(lang,_)|lang.to_ascii_lowercase()).collect();for(lang,url)in &source.hreflang{
  let target=by.get(url.as_str()).copied();let checked=target.is_some_and(|target|target.status==200&&target.content_type.to_ascii_lowercase().contains("html")&&target.html_extracted==Some(true));let returns:Vec<_>=target.into_iter().flat_map(|target|&target.hreflang).filter(|(_,back)|back==&source.url).collect();
  let missing=checked&&returns.is_empty();let inconsistent=checked&&!self_languages.is_empty()&&returns.iter().any(|(label,_)|!self_languages.contains(&label.to_ascii_lowercase()));let noncanonical=target.is_some_and(|target|!target.canonical.is_empty()&&target.canonical!=target.url);let noindex=target.is_some_and(|target|crate::directives::restriction(target,"googlebot","noindex"));let unlinked=!linked.contains(url.as_str());
  let include=match kind{"all-hreflang"=>true,"non-200-hreflang"=>target.is_some_and(|target|target.status!=200),"unlinked-hreflang"=>unlinked,"missing-hreflang-returns"=>missing,"inconsistent-hreflang-returns"=>inconsistent,"noncanonical-hreflang"=>noncanonical,"noindex-hreflang"=>noindex,_=>false};if !include{continue}if report.rows.len()==50000{report.truncated=true;return Ok(report)}
  let mut findings=Vec::new();if target.is_none(){findings.push("Target not crawled (unknown response)")}if target.is_some_and(|target|target.status!=200){findings.push("Observed non-200 response")}if missing{findings.push("Missing recorded return link")}if inconsistent{findings.push("Inconsistent recorded return language")}if noncanonical{findings.push("Target canonical points elsewhere")}if noindex{findings.push("Target has observed noindex")}if unlinked{findings.push("No observed hyperlink inlink")}
  report.rows.push(vec![source.url.clone(),lang.clone(),url.clone(),target.map(|target|target.status.to_string()).unwrap_or_default(),if unlinked{"No"}else{"Yes"}.into(),if !checked{"Unknown: target not verified HTTP 200 extracted HTML"}else if missing{"Missing"}else{"Observed"}.into(),self_languages.iter().cloned().collect::<Vec<_>>().join(", "),findings.join("; ")]);
 }}Ok(report)
}
pub fn load(db:&str,kind:&str)->Result<Report>{
 if KINDS[..7].contains(&kind){return hreflang(&crate::load_project_data(db)?.pages,kind)}
 if !KINDS[7..].contains(&kind){return Err("Unknown relationship report".into())}
 let saved=crate::pagination::analyze(db)?;let mut report=Report{kind:kind.into(),headers:["Source","Relation","Target","Target Status","Observed Hyperlink Inlink","Return Link","Source Kind","Findings"].into_iter().map(String::from).collect(),rows:Vec::new(),truncated:false,scope:format!("Saved-source pagination analysis only. {} eligible HTML pages; {} saved sources missing. Unknown responses are blank and excluded from the non-200 report. Unlinked is bounded to saved internal hyperlink observations. No network requests. 50000-row report limit.",saved.summary.eligible_html,saved.summary.missing_sources.len())};
 for row in saved.rows{let include=if kind=="non-200-pagination"{row.target_status.is_some_and(|status|status!=200)}else{!row.observed_hyperlink_inlink};if !include{continue}if report.rows.len()==50000{report.truncated=true;break}report.rows.push(vec![row.source,row.relation,row.target,row.target_status.map(|status|status.to_string()).unwrap_or_default(),if row.observed_hyperlink_inlink{"Yes"}else{"No"}.into(),row.return_link,row.source_kind,row.findings.join("; ")]);}Ok(report)
}
#[cfg(test)]mod tests{use super::*;
 fn page(name:&str)->Page{Page{url:format!("https://e.test/{name}"),status:200,content_type:"text/html".into(),html_extracted:Some(true),..Default::default()}}
 #[test]fn hreflang_reports_distinguish_unknown_missing_and_wrong_language(){let mut he=page("he");he.hreflang=vec![("he".into(),he.url.clone()),("en".into(),"https://e.test/en".into()),("fr".into(),"https://e.test/unknown".into()),("de".into(),"https://e.test/error".into())];let mut en=page("en");en.hreflang=vec![("en".into(),he.url.clone())];let mut error=page("error");error.status=404;let pages=vec![he,en,error];assert_eq!(hreflang(&pages,"all-hreflang").unwrap().rows.len(),5);assert_eq!(hreflang(&pages,"non-200-hreflang").unwrap().rows.len(),1);assert_eq!(hreflang(&pages,"inconsistent-hreflang-returns").unwrap().rows.len(),1);assert!(hreflang(&pages,"missing-hreflang-returns").unwrap().rows.is_empty());let unknown=hreflang(&pages,"all-hreflang").unwrap().rows.into_iter().find(|row|row[2].ends_with("unknown")).unwrap();assert_eq!(unknown[3],"");assert!(unknown[5].starts_with("Unknown"));}
 #[test]fn noindex_canonical_linked_and_legacy_unknown_are_separate(){let mut a=page("a");a.hreflang=vec![("he".into(),a.url.clone()),("en".into(),"https://e.test/b".into())];a.links=vec![crate::Link{kind:"anchor".into(),url:"https://e.test/b".into(),..Default::default()}];let mut b=page("b");b.directives="noindex".into();b.canonical=a.url.clone();let pages=vec![a.clone(),b.clone()];assert_eq!(hreflang(&pages,"missing-hreflang-returns").unwrap().rows.len(),1);assert_eq!(hreflang(&pages,"noindex-hreflang").unwrap().rows.len(),1);assert_eq!(hreflang(&pages,"noncanonical-hreflang").unwrap().rows.len(),1);assert_eq!(hreflang(&pages,"unlinked-hreflang").unwrap().rows.len(),1);b.html_extracted=None;assert!(hreflang(&[a,b],"missing-hreflang-returns").unwrap().rows.is_empty());assert!(hreflang(&[],"invalid").is_err());}
}
